"""Generate compact, traceable results from final audited measurements only."""
import collections,csv,datetime,json,math,shutil,statistics as st,time
from pathlib import Path
from common import V,load,save,sha
from prepare_rtx import root
from export_measurements import csvfile
def readcsv(p):return list(csv.DictReader(Path(p).open(encoding='utf8')))
def mean(rows,k):return st.mean(float(x[k]) for x in rows if x.get(k) not in ['',None]) if any(x.get(k) not in ['',None] for x in rows) else None
def main():
    r=root();out=V/'results';out.mkdir();core=load(r/'core_analysis/ANALYSIS.json');p0=load(r/'p0_analysis/ANALYSIS.json');h=readcsv(r/'core_analysis/HOST_COSTS.csv');trace=readcsv(r/'trace_analysis/TRACE_CALLS.csv');th=load(r/'trace_analysis/TRACE_HOSTS.json');a=load(r/'core_analysis/AUDIT.json');arc=load(Path(str(r)+'-archive')/'ARCHIVE.json');fresh=load(Path(str(r)+'-archive')/'FRESH_RECOMPUTE.json');resource=load(r/'RESOURCE_SUMMARY.json')
    for name,source in [('ANALYSIS.json',r/'core_analysis/ANALYSIS.json'),('P0_ANALYSIS.json',r/'p0_analysis/ANALYSIS.json'),('HOST_COSTS.csv',r/'core_analysis/HOST_COSTS.csv'),('CORE_COVERAGE.csv',r/'core_analysis/COVERAGE.csv'),('P0_COVERAGE.csv',r/'p0_analysis/COVERAGE.csv'),('MODE_EVIDENCE.csv',r/'core_analysis/MODE_EVIDENCE.csv'),('WARMUP_AND_SETUP.csv',r/'cost_analysis/WARMUP_AND_SETUP.csv')]:shutil.copyfile(source,out/name)
    api=collections.defaultdict(list)
    for x in readcsv(r/'cost_analysis/PROFILED_GRAPH_API_COSTS.csv'):api[x['case_id'],x['layout'],x['mode'],x['name'],'warmup' if int(x['call'])<2 else 'formal'].append(float(x['profiled_API_interval_us']))
    csvfile(out/'PROFILED_GRAPH_API_SUMMARY.csv',[dict(case_id=k[0],layout=k[1],mode=k[2],API=k[3],phase=k[4],samples=len(v),mean_us=st.mean(v),median_us=st.median(v),p95_us=sorted(v)[math.ceil(.95*len(v))-1],max_us=max(v),scope='profiled API wall interval;observer included;not clean') for k,v in sorted(api.items())])
    timed=[x for x in h if x['stage']=='confirm' and x['numerical_qualified']=='True' and x['environment_qualified']=='True'];absolute=[]
    for gid in [c['geometry_id'] for c in load(r/'plan.json')['cases'][::2]]:
        for mode in ['OFF','ON']:
            selected=[x for x in timed if x['case_id'].startswith(gid+'-v') and x['mode']==mode];row=dict(geometry_id=gid,mode=mode,qualified_hosts=len(selected))
            for arm in ['PQ','QB_A','QH_C','QB_B']:
                rows=[x for x in selected if x['arm']==arm];row[arm+'_completed_graph_us']=mean(rows,'resident_mean_us');row[arm+'_resident_call_us']=mean(rows,'resident_call_mean_us')
            absolute.append(row)
    csvfile(out/'ABSOLUTE_COSTS.csv',absolute)
    def flatten(rows):
        result=[]
        for x in rows:
            z=x['summary'];result.append({k:v for k,v in x.items() if k!='summary'}|{k:v for k,v in z.items() if k not in ['pairs','leave_one_block_out']})
        return result
    csvfile(out/'GEOMETRY_CONTRASTS.csv',flatten(core['geometry_contrasts']));csvfile(out/'CASE_CONTRASTS.csv',flatten(core['case_contrasts']));csvfile(out/'PRODUCER_CONTRASTS.csv',flatten(p0['geometry_contrasts']))
    for path in (r/'interpretation').iterdir():shutil.copyfile(path,out/path.name)
    ts=[]
    for host in th:
        rows=[x for x in trace if x['task_id']==host['task_id'] and x['warmup']=='False'];ts.append(dict(task_id=host['task_id'],case_id=host['case_id'],mode=host['mode'],layout=host['layout'],formal_calls=len(rows),kernel_count_mean=mean(rows,'kernels'),kernel_duration_sum_mean_us=mean(rows,'kernel_duration_sum_us'),kernel_span_mean_us=mean(rows,'kernel_span_us'),copies_mean=mean(rows,'copies'),copy_bytes_mean=mean(rows,'copy_bytes'),unmapped_records=host['unmapped_kernel_or_copy_records'],kernel_names=host['kernel_names'],scope='profiled actual timeline,not clean latency;kernel sum is not union busy time;C0 copy call tags include adjacent update'))
    csvfile(out/'TRACE_SUMMARY.csv',ts)
    shutil.copyfile(r/'p0_analysis/HOST_COSTS.csv',out/'P0_HOST_COSTS.csv')
    producers=[x for x in readcsv(r/'p0_analysis/HOST_COSTS.csv') if x['stage']=='producer' and x.get('environment_qualified')=='True'];pt=[]
    for q in [2,4]:
        for arm in ['QB_permuted','QH_permuted','QB_compact','QH_compact']:
            rows=[x for x in producers if x['case_id'].startswith(f'producer-q{q}-') and x['arm']==arm];pt.append(dict(q=q,arm=arm,mode='OFF',hosts=len(rows),**{key:mean(rows,key) for key in ['integrated_q_update_mean_us','Q_copy_or_transpose_mean_us','Q_upload_and_sync_mean_us','compute_return_mean_us','explicit_sync_mean_us','readback_mean_us','resident_mean_us','resident_call_mean_us']}))
    csvfile(out/'PRODUCER_TRANSACTIONS.csv',pt)
    resource['post_restore_storage']=load(Path(str(r)+'-fresh')/'RESTORE.json')['storage'];resource['CPU_replay_seconds']=fresh['CPU_seconds'];resource['CPU_delivery_wall_seconds_at_report']=time.time()-datetime.datetime.fromisoformat(load(r/'GPU_EXECUTION_CLOSED.json')['utc']).timestamp()
    save(V/'RAW_LOCATION.json',dict(**arc,fresh_restore=fresh,remote_raw_uploaded=False,external_review=False));save(V/'RESOURCE_SUMMARY.json',resource)
    save(V/'CAPABILITY_RESULT.json',dict(status='ACTUAL_ON_AND_TIMELINE_ESTABLISHED',original_installed_tools_receipt='CAPABILITY.json is historical before bounded tool download',actual_ON_signatures=a['actual_ON_signatures'],qualification_hosts=144,profile_attempts=resource['profile_attempts'],completed_trace_hosts=23,one_preserved_CUPTI_startup_failure=True,old_numerical_DLLs_unchanged=True,CUDA_Graph='capture/end/instantiate/launch successful API exits for all formal call indices;no formal recapture in profiled qualification;clean mode bound by same signature/runtime/environment',ON_clean_scope='qualification trace covers signatures;clean hosts are deliberately unprofiled,not per-host traced',C0_alternating_updates='both values full QKV/mask updates in persistent buffers,OFF/ON QB/QH;full input readback and ordinary exact',P0_mode='OFF separately frozen to stay within total24profile attempts;not an ON conversion claim',telemetry='SM clock UNKNOWN;new idle SMI/NVML both0;memory.used differs between SMI0 and NVML296747008;no arbitrary normalization or root-cause attribution',hardware='SOFTWARE_FIRST/HOLD'))
    def contrast(gid,mode,label):return next(x['summary'] for x in core['geometry_contrasts'] if x['geometry_id']==gid and x['mode']==mode and x['comparison']==label)
    save(V/'SCIENTIFIC_FINDINGS.json',dict(mode_contrasts=[x for x in core['geometry_contrasts'] if x['mode']=='ON/OFF'],mapping_contrasts=[x for x in core['geometry_contrasts'] if x['comparison'] in ['QB_QH','QB_QH_alt','AA']],producer_contrasts=p0['geometry_contrasts'],observations=['verified replay materially reduces completed host graph costs on selected inputs','OFF mapping gaps narrow under ON;small residuals require same-unit AA/practical-scale caution','1024 kernel-path boundary actually observed;physical bottleneck not established','P0 OFF charges real continuous conversion and transfer;no ON producer claim'],hardware='SOFTWARE_FIRST/HOLD',natural_decoder='UNKNOWN'))
    lines=['# PR122：图重放、1024邻界与完整Q转换成本','', '**原生实现、双模式资格、八块核心采集及独立OFF连续转换面板已完成。硬件保持SOFTWARE_FIRST/HOLD。**','',f"实际{a['hosts']:,}个GPU原生宿主，{a['graph_calls']:,}次显式ggml图调用；其中1个CUPTI接入宿主在首图前失败并保留。正式clean/P0无科学重跑。旧PR121/120/118均未恢复。",'', '|阶段|宿主|图调用|状态|','|---|---:|---:|---|']
    for stage,z in a['by_stage'].items():lines.append(f"|{stage}|{z['hosts']}|{z['calls']}|{z['qualified']}完成控制检查|")
    lines+=['','## 1. 映射与模式资格','', '完整输入来自PR121已封存坐标，逐字节核验，未使用旧输出充当新重复。核心44个新serial-q1宿主；两模式144个资格宿主，每个2warmups+32次，ordinary均精确对应新参考。q4转换另有16个新serial宿主及32个路径资格宿主。输入前后、真实CUDA放置、节点支持、共享核心与41个插件导入、计算返回及同步均复核。这里未重新采集中间QK/softmax/AV四阶段，不声称全域等价或数学真值优越。','', '通过轻量官方CUPTI工具取得真实capture/end/instantiate/launch和kernel活动。18个布局坐标对应16个不同ON签名（q1公共链复用同签名）；正式期32次均逐次重放且无重捕获。clean宿主不加载CUPTI，通过相同图签名、冻结运行时/环境和资格证据绑定模式，不把未追踪的每个clean进程说成已直接trace。两值模式的完整QKV/mask交替更新在同一持久buffer中通过。','', '初版CUPTI回调错误读取非launch回调中未定义的symbolName，首个ON能力宿主访问异常。错误收据/原冻结永久保留，修正工具字段使用后新冻结；原始OFF参考与OFF能力收据以原身份引用。不是QH数值失败。其后所有数值与正式块合格；不把失败抹成一次无失败运行。','', '## 2. 核心完成成本与A/A','', '单位µs；下表等权汇总两个值模式、八块独立宿主均值。QPCl区间为图调用入口至全设备同步完成，非kernel时间。比值QBA/QHC>1表示QH点估计较低；ON/OFF<1表示重放模式较低。必须同时阅读第二QB、A/A、分值模式/实际session、区间及全部逐坐标表。','', '|几何|模式|PQ|QB_A|QH_C|QB_B|QB_A/QH_C|QB_A/QB_B|','|---|---|---:|---:|---:|---:|---:|---:|']
    for x in absolute:
        gid,mode=x['geometry_id'],x['mode'];c=contrast(gid,mode,'QB_QH');aa=contrast(gid,mode,'AA');lines.append(f"|{gid}|{mode}|{x['PQ_completed_graph_us']:.3f}|{x['QB_A_completed_graph_us']:.3f}|{x['QH_C_completed_graph_us']:.3f}|{x['QB_B_completed_graph_us']:.3f}|{c['ratio']:.6f}|{aa['ratio']:.6f}|")
    lines+=['','|几何|QB_A ON/OFF|QB_B ON/OFF|QH_C ON/OFF|','|---|---:|---:|---:|']
    for gid in dict.fromkeys(x['geometry_id'] for x in absolute):lines.append('|'+gid+'|'+'|'.join(f"{contrast(gid,'ON/OFF',arm)['ratio']:.6f}" for arm in ['QB_A','QB_B','QH_C'])+'|')
    lines+=['','QB_A/B调用完全相同QB代码，不能择快。30次内循环是技术重复；描述性bootstrap重采集整个块并按两个真实session分层，两个session不是独立日期/设备总体。完整CI、逐块和leave-one-block-out保留于ANALYSIS.json。2%/1µs与对应A/A仅作既定实用尺度检查，不是显著性/等价证书；不从单点>1.02宣称稳定加速。','', '冷初始化/身份审计、图构建、分配、源读取、物化、首次upload/sync、所有warmup、resident-call及readback单列。真实捕获API耗时来自profile宿主，含观察器开销；不能用它冒充精确clean捕获税或精确摊销点。所有逐调用原始QPC和完整输出留在本地归档。','', '## 3. 1024与compact-Q机制','', '在匹配q2/d128/Hq32/Hkv8、值模式0的实际timeline中，QB在1023/1025 keys为8个kernel，1024为3个；PQ为17→7→17，QH_C为10→5→10。OFF的QB三点同样8→3→8。1023/1025包含转换、batched-pointer准备及cuBLAS GEMV/hgemm命名的kernel；1024出现不同的GGML mul_mat与1024-softmax专用kernel。完整mangled名称、stream、graph/node关联、原始API与device时间均保留。支持BACKEND_BOUNDARY_OBSERVED，不是用CPU节点数猜kernel数。','', 'q2/256的QH_C从permuted到compact为5→4个kernel，重复的cpy_scalar出现次数降低，而不是新增一种算术。两种存储有完整数值资格。此证据局限于这些实际trace坐标/observer；改变key extent同时改变causal frontier，尚未单独隔离dispatch条件，也未测量物理traffic、occupancy或Tensor Core利用率。kernel duration之和不是并行busy时间，trace开销不并入clean成本。','', '## 4. 连续Q转换事务（独立OFF面板）','', '为遵守含首个失败在内24个profile宿主上限，q4未再扩展ON签名追踪，P0在打开其GPU结果前独立冻结为统一OFF。它不改变核心dual计划，不把OFF结果冒作ON。所有路径从相同预存在permuted host Q起算，目标预分配、KV/mask常驻；实际单段计时含copy/transpose→Q上传及完成→图执行及同步→完整ordinary readback，没有相加独立CPU/GPU均值。','', '|q|路径|完整事务 µs|CPU copy/transpose|Q upload/sync|compute返回|额外sync|readback|','|---:|---|---:|---:|---:|---:|---:|---:|']
    for x in pt:lines.append(f"|{x['q']}|{x['arm']}|{x['integrated_q_update_mean_us']:.3f}|{x['Q_copy_or_transpose_mean_us']:.3f}|{x['Q_upload_and_sync_mean_us']:.3f}|{x['compute_return_mean_us']:.3f}|{x['explicit_sync_mean_us']:.3f}|{x['readback_mean_us']:.3f}|")
    lines+=['','完整配对比值、两值/session方向及区间见P0_ANALYSIS.json。此四路径面板没有相同实现重复arm，不能借核心A/A认证其细小效应精度。最初产生Q的模型成本、KV更新、自然decoder与ON连续事务仍UNKNOWN。冷分配及KV/mask初次上传另列，不假定请求中免费。','', '## 5. 资源、证据与边界','',f"实际GPU原生宿主{a['hosts']}，profile尝试{resource['profile_attempts']}（23成功trace+1首图前工具失败）；能力宿主5，显式设备端点查询{resource['SMI_queries']}，另有7次NVML接口调用。主机/辅助进程、墙钟/owned保守核算、内存、存储和CPU交付见RESOURCE_SUMMARY.json。一个GPU worker；总六小时、末45分钟交付预算内完成。",'', 'SM时钟通道保持UNKNOWN：历史异常未改写，新idle SMI与NVML均返回0，不足以证明活动频率有效；SMI memory.used=0与NVML报告不同，未作任意单位缩放或归因。设备/driver与reported quiet/free/温度/AC门槛保留；端点通过不证明持续独占，也不能做频率归一化。完整reported记录留本地，不按延迟删点。','',f"原始归档：`{arc['archive_path']}`，{arc['members']}成员，{arc['archive_bytes']}bytes；SHA256 `{arc['archive_sha256']}`。Manifest `{arc['manifest_sha256']}`。全部成员fresh restore，核心/P0分析、实际trace汇总、成本边界和PE/IAT审计在新解释器中独立复算一致。RAW_LOCAL_ONLY，无远端raw认证或第三方独立审查。",'', '**结论边界：** 图模式、表示和后端邻界现有受控成本/trace证据，见全部配对数据；尚未证明强软件基线后存在需要新硬件的物理瓶颈及系统关键路径。保持SOFTWARE_FIRST/HOLD。没有运行actor/decoder/W1、RTL/FPGA，也未修改B570、论文、main或发布。','']
    (V/'RESULT.md').write_text('\n'.join(lines).replace('QPCl','QPC'),encoding='utf8')
    print('generated RESULT and compact tables')
if __name__=='__main__':main()
